package com.speaksheet.data

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.room.migration.Migration
import androidx.sqlite.db.SupportSQLiteDatabase

@Database(entities = [RecentFile::class, SheetEntity::class], version = 4, exportSchema = false)
abstract class AppDatabase : RoomDatabase() {

    abstract fun recentFileDao(): RecentFileDao
    abstract fun sheetDao(): SheetDao

    companion object {
        @Volatile
        private var INSTANCE: AppDatabase? = null

        val MIGRATION_3_4 = object : Migration(3, 4) {
            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL("""
                    CREATE TABLE IF NOT EXISTS `file_sheets` (
                        `id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
                        `fileUri` TEXT NOT NULL,
                        `sheetName` TEXT NOT NULL,
                        `sheetIndex` INTEGER NOT NULL,
                        `zoom` REAL NOT NULL,
                        `scrollX` REAL NOT NULL,
                        `scrollY` REAL NOT NULL,
                        `frozenRows` INTEGER NOT NULL,
                        `frozenCols` INTEGER NOT NULL,
                        FOREIGN KEY(`fileUri`) REFERENCES `recent_files`(`uri`) ON UPDATE NO ACTION ON DELETE CASCADE
                    )
                """.trimIndent())
                db.execSQL("CREATE INDEX IF NOT EXISTS `index_file_sheets_fileUri` ON `file_sheets` (`fileUri`)")
                db.execSQL("CREATE INDEX IF NOT EXISTS `index_file_sheets_fileUri_sheetIndex` ON `file_sheets` (`fileUri`, `sheetIndex`)")

                // Treat existing files as "Sheet1"
                db.execSQL("""
                    INSERT INTO `file_sheets` (`fileUri`, `sheetName`, `sheetIndex`, `zoom`, `scrollX`, `scrollY`, `frozenRows`, `frozenCols`)
                    SELECT `uri`, 'Sheet1', 0, 1.0, 0.0, 0.0, 0, 0 FROM `recent_files`
                """.trimIndent())
            }
        }

        fun getDatabase(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "speaksheet_database"
                )
                .addMigrations(MIGRATION_3_4)
                .fallbackToDestructiveMigration(dropAllTables = true)
                .build()
                INSTANCE = instance
                instance
            }
        }
    }
}

package com.speaksheet.data

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Transaction
import kotlinx.coroutines.flow.Flow

@Dao
interface RecentFileDao {
    @Query("SELECT COUNT(*) FROM recent_files")
    suspend fun getRecentFilesCount(): Int

    @Query("SELECT * FROM recent_files ORDER BY lastModified DESC LIMIT 50")
    fun getAllRecentFiles(): Flow<List<RecentFile>>

    @Query("SELECT * FROM recent_files ORDER BY lastModified DESC")
    suspend fun getRecentFilesList(): List<RecentFile>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertRecentFile(recentFile: RecentFile)

    @Query("DELETE FROM recent_files WHERE uri = :uri OR (path = :path AND path != '')")
    suspend fun deleteByUriOrPath(uri: String, path: String)

    @Query("DELETE FROM recent_files WHERE uri = :uri")
    suspend fun deleteRecentFileByUri(uri: String)

    @Query("DELETE FROM recent_files WHERE uri LIKE 'sample://%'")
    suspend fun deleteSampleFiles()

    @Transaction
    suspend fun upsertRecentFile(recentFile: RecentFile) {
        deleteByUriOrPath(recentFile.uri, recentFile.path)
        insertRecentFile(recentFile)
    }
}

package com.speaksheet.data

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Update
import kotlinx.coroutines.flow.Flow

@Dao
interface SheetDao {
    @Query("SELECT * FROM file_sheets WHERE fileUri = :fileUri ORDER BY sheetIndex ASC")
    suspend fun getSheetsForFile(fileUri: String): List<SheetEntity>

    @Query("SELECT * FROM file_sheets WHERE fileUri = :fileUri ORDER BY sheetIndex ASC")
    fun observeSheetsForFile(fileUri: String): Flow<List<SheetEntity>>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertSheet(sheet: SheetEntity): Long

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertSheets(sheets: List<SheetEntity>)

    @Update
    suspend fun updateSheet(sheet: SheetEntity)

    @Query("DELETE FROM file_sheets WHERE fileUri = :fileUri")
    suspend fun deleteSheetsForFile(fileUri: String)

    @Query("DELETE FROM file_sheets WHERE fileUri = :fileUri AND sheetName = :sheetName")
    suspend fun deleteSheet(fileUri: String, sheetName: String)

    @androidx.room.Transaction
    suspend fun replaceSheetsForFile(fileUri: String, sheets: List<SheetEntity>) {
        deleteSheetsForFile(fileUri)
        insertSheets(sheets)
    }
}

