            val cellDesc = if (spreadsheetEngine.isBannerRow(row)) "Banner Row ${row + 1}" else "${spreadsheetEngine.getColumnName(targetCol)}${row + 1}"
            spreadsheetEngine.pushUndo("Edit $cellDesc")
