        val lastNonEmpty = values.indexOfLast { it.isNotEmpty() }
        val trimmedValues = if (lastNonEmpty >= 0) values.subList(0, lastNonEmpty + 1) else emptyList()
        val clipText = trimmedValues.joinToString("\n")

